UPDATE privileged_mfa_attestation_grant
SET revoked_at = UTC_TIMESTAMP(6),
    revoked_by_user_id = #{revokedByUserId}
WHERE grantee_user_id = #{granteeUserId}
  AND org_id = #{orgId}
  AND redeemed_at IS NULL
  AND revoked_at IS NULL

